import{_ as t,o as _,c as l,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/82-团块次代“上流”女性期望孩子既高雅又国际化.md","filePath":"books/xialiu-shehui/82-团块次代“上流”女性期望孩子既高雅又国际化.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/82-团块次代“上流”女性期望孩子既高雅又国际化.md"};function n(r,a,i,p,d,u){return _(),l("div",null,[...a[0]||(a[0]=[e("h2",{id:"团块次代-上流-女性期望孩子既高雅又国际化",tabindex:"-1"},[s("团块次代“上流”女性期望孩子既高雅又国际化 "),e("a",{class:"header-anchor",href:"#团块次代-上流-女性期望孩子既高雅又国际化","aria-label":'Permalink to "团块次代“上流”女性期望孩子既高雅又国际化"'},"​")],-1),e("p",null,"从以上调查结果来看，具有鲜明特征的是不少团块次代上流阶层的女性，无论对男孩子还是对女孩子，都希望他们有“高雅的举止”，而且这一世代在此方面显现出的阶层差异要比新人类世代更显著。同样，无论对男孩子还是对女孩子，希望自己的孩子“掌握外语”、接受“英才教育”、“参加志愿者或国际贡献活动”的，也都是上流阶层的女性较多，且较之新人类世代同样更显现出阶层的差异。",-1),e("p",null,"综上所述，可以发现团块次代的“上流”女性教育下一代的观念似乎是要将孩子培养成既高雅又兼具国际化的国际通用型人才，这种倾向较中流阶层更为明显，而下流阶层的女性则几乎没有这样的想法。",-1),e("p",null,"需要指出的是，团块次代“上流”女性中有海外留学或派驻海外工作经验的人占29.4%，比例相当高。这个数字仅比团块次代上流阶层男性的35.7%略低。也就是说，许多团块次代上流阶层的女性可能因为父亲工作的关系，有过在海外居住和生活的经验，也就是所谓的“归国子女”，还有不少赴海外留学考取各种资格的人。或许正是基于这些自己的亲身经验，使她们养成了将孩子培养成国际通用型人才的教育观念。",-1),e("p",null,"与此相对，团块次代下流阶层女性的教育观念则是让孩子拥有一技之长，从而可以按照自己的价值观自由自在地生活。",-1),e("p",null,"当然，不论哪一种生活方式都应该受到尊重。但是，属于下流阶层的父母也会希望自己的孩子能够跻身上流阶层，这时就会产生各种各样的问题了。",-1),e("p",null,"今后越是年轻的世代，阶层意识的差距可能会愈加明显。笔者从在大企业里工作的熟人那里听说，如今经济不景气，在竞争激烈的“就业战争”中胜出的新职员，名副其实学业优秀，大多拥有留学经验，且有着强烈的优越感，但他们所从事的却是类似于走街串巷推销的工作，甚至有的需要昼伏夜出、披星戴月。这些新职员都是从小学开始就要经过入学考试的一代，他们从小就经历了各种各样的“选拔”，而且是一群只与自己同阶层的人来往的年轻人，如今开始踏上社会了，这些有着强烈优越感的人能否胜任这样粗重的工作？他们能够体会普通大众的心情吗？实在令人为之担忧。",-1)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
